-- Central trust/safety moderation. Rules and evidence are intentionally private.
create table public.content_moderation_rules(
 id uuid primary key default gen_random_uuid(),label text not null,pattern text not null,
 category text not null check(category in('sexual_explicit','sexual_solicitation','harassment','threats_violence','self_harm','hate','predatory','personal_information','spam_scam')),
 severity text not null check(severity in('low','medium','high','urgent')),
 action text not null check(action in('warn','block','review','urgent_review')),
 active boolean not null default true,version integer not null default 1,created_by uuid references public.stables(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table public.content_moderation_events(
 id uuid primary key default gen_random_uuid(),author_id uuid references public.stables(id)on delete set null,
 content_type text not null,content_id text,context jsonb not null default'{}',category text not null,severity text not null,action text not null,
 rule_id uuid references public.content_moderation_rules(id)on delete set null,rule_version integer,content_evidence text not null,
 status text not null default'pending'check(status in('pending','reviewed','dismissed','actioned')),reviewed_by uuid references public.stables(id),review_note text,created_at timestamptz not null default now(),reviewed_at timestamptz
);
alter table public.content_moderation_rules enable row level security;alter table public.content_moderation_rules force row level security;
alter table public.content_moderation_events enable row level security;alter table public.content_moderation_events force row level security;
create index content_moderation_queue_idx on public.content_moderation_events(status,created_at desc);

